def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    desperate_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 100:
                    aggressive_count += 1

    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22
    critical = hp <= 3 or no_water_days >= 1
    very_safe = hp >= 8 and no_water_days == 0

    base = 0.0

    if critical:
        base = max(108.0, highest_prev + 3.0)
        if tight_supply:
            base += 8.0
    elif tight_supply:
        base = max(82.0, avg_prev * 0.82, highest_prev * 0.72)
        if aggressive_count >= 2:
            base += 8.0
        if desperate_count >= 1:
            base += 6.0
    elif loose_supply and very_safe:
        base = max(18.0, avg_prev * 0.22)
    else:
        base = max(42.0, avg_prev * 0.45, highest_prev * 0.38)
        if aggressive_count >= 2:
            base += 5.0

    days_left = max(0, 10 - int(day))
    reserve_target = days_left * 28.0
    affordable = budget
    if budget > reserve_target:
        affordable = max(0.0, budget - reserve_target * 0.35)

    if critical:
        affordable = budget

    bid = min(base, affordable, budget)

    if critical and bid < min(budget, 95.0):
        bid = min(budget, 95.0)
    if very_safe and loose_supply:
        bid = min(bid, 35.0)

    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    potential_slots = int(day_context['supply'] / WATER_REQ)

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    if my_status['no_water_days'] >= 1:
        desperation_bid = DAILY_SALARY * 0.9 + (my_status['no_water_days'] * 5)
        return min(my_status['budget'], desperation_bid)

    eric_bid_yesterday = 0.0
    highest_prev_bid_among_alive = 0.0

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid_value = prev['bid']
                highest_prev_bid_among_alive = max(highest_prev_bid_among_alive, bid_value)
                if opp_id == "Eric":
                    eric_bid_yesterday = bid_value

    base_bid = DAILY_SALARY * 0.55

    if eric_bid_yesterday > 0:
        if potential_slots <= 1:
             base_bid = max(base_bid, eric_bid_yesterday + 10)
        else:
            base_bid = max(base_bid, eric_bid_yesterday + 2)
    elif highest_prev_bid_among_alive > 0:
        if potential_slots <= 1:
            base_bid = max(base_bid, highest_prev_bid_among_alive + 7)
        else:
            base_bid = max(base_bid, highest_prev_bid_among_alive + 1)

    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents >= potential_slots:
        competition_factor = 1.0 + (num_alive_opponents - potential_slots) * 0.1
        base_bid = max(base_bid, DAILY_SALARY * 0.6 * competition_factor)

    if my_status['no_water_days'] == 0:
        base_bid = min(base_bid, DAILY_SALARY * 0.95)

    final_bid = min(my_status['budget'], base_bid)

    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_BID = 10
    DAY = int(day_context['day']) if isinstance(day_context['day'], float) else day_context['day']
    SUPPLY = day_context['supply']
    if isinstance(SUPPLY, float):
        SUPPLY = int(SUPPLY)
    hp = my_status['hp']
    budget = my_status['budget']
    base_bid = DAILY_SALARY * 0.4
    alive_opps = [o for o in opponents_status.values() if o['alive']]
    if not alive_opps:
        return min(budget, base_bid)
    # collect yesterday's bids from alive opponents
    prev_bids = []
    for opp in alive_opps:
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            prev_bids.append(trace['bid'])
    if prev_bids:
        max_prev = max(prev_bids)
        target = max(base_bid, min(DAILY_SALARY * 1.0, max_prev + 2.0))
    else:
        target = base_bid
    # adjust based on hp
    if hp <= 2:
        target = DAILY_SALARY * 0.9
    # if no water days > 2, increase
    if my_status['no_water_days'] >= 2:
        target = max(target, DAILY_SALARY * 0.85)
    # final cap
    target = min(budget, target)
    if target > DAILY_SALARY:
        target = DAILY_SALARY
    return max(MIN_BID, target)
